import * as _enum from './lib';
import { Implementation } from './Implementation';
import { Model } from './Model';
import { ViewController } from './ViewController';

export class NCanvas {
    viewController: ViewController;
    model: Model;
    implementation: Implementation;


    divHost: HTMLElement;
    public static Init(id: string) {
        new NCanvas(id);
    }
    constructor(id: string) {
        const divHost = document.getElementById(id);
        if (divHost) { this.divHost = divHost; }

        this.model = new Model(this, id);
        this.implementation = new Implementation(this);
        this.viewController = new ViewController(this);
        console.log(this);
    }
}



export class Solution {
    public divHost: HTMLElement;

    constructor(id: string, index = 0) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        const div = document.createElement('div');
        div.id ='block-game';
        div.style.width = '100%';
        div.style.height = '100%';
        this.divHost.appendChild(div);

        NCanvas.Init(div.id);
    }
    public destroy() {
        try {
            while (this.divHost && this.divHost.lastElementChild) {
                const lastChild = this.divHost.lastElementChild as Node;
                this.divHost.removeChild(lastChild);
            }
        } catch (error) {
            console.error('Error removing child elements:', error);
        }
        
    }
}